INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Farbmodell nur für Bildschirme relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Druck, Fotografie"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt ein Farbmodell?', 3, '[{"text": "Farben systematisch darstellen", "correct": true, "because": "Konsistente Reproduktion"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kein Sicherheitsfokus"}, {"text": "Netzwerke verbinden", "correct": false, "because": "Nicht Netzwerkbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Farbmodelle sind weit verbreitet?', 5, '[{"text": "RGB", "correct": true, "because": "Additives Modell für Bildschirme"}, {"text": "CMYK", "correct": true, "because": "Subtraktives Modell für Druck"}, {"text": "TXT", "correct": false, "because": "Kein Farbmodell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) RGB ist ein additives Farbmodell. b) CMYK ist nur für Bildschirme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CMYK für Druck"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Farbmodell?', 4, '[{"text": "Farbkomponenten", "correct": false, "because": "Grundlage"}, {"text": "Anwendungsbereich", "correct": false, "because": "Bestimmt Nutzung"}, {"text": "Papiergewicht", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das RGB-Modell subtraktiv ist?', 2, '[{"text": "Nein", "correct": true, "because": "Additiv"}, {"text": "Ja", "correct": false, "because": "Lichtmischung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Farbmodell wird für den Druck verwendet?', 3, '[{"text": "CMYK", "correct": true, "because": "Subtraktive Mischung"}, {"text": "RGB", "correct": false, "because": "Für Bildschirme"}, {"text": "HSB", "correct": false, "because": "Designfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Farbmodell?', 5, '[{"text": "Konsistente Farbdarstellung", "correct": true, "because": "Standardisierung"}, {"text": "Präzise Farbanpassung", "correct": true, "because": "Kontrolle möglich"}, {"text": "Erhöhte Netzwerkgeschwindigkeit", "correct": false, "because": "Kein Netzwerkbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das RGB-Modell nutzt Licht. b) CMYK ist für Bildschirme. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CMYK für Druck"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Farbmodell?', 4, '[{"text": "Farbkomponenten", "correct": false, "because": "Grundlage"}, {"text": "Anwendungskontext", "correct": false, "because": "Bestimmt Modell"}, {"text": "Papierdokumentation", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das HSB-Modell für den Druck geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Designfokus"}, {"text": "Ja", "correct": false, "because": "CMYK üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten hat das RGB-Modell?', 4, '[{"text": "Rot", "correct": true, "because": "Red"}, {"text": "Grün", "correct": true, "because": "Green"}, {"text": "Gelb", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Farbmodelle nur für Grafikdesign sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Druck, Video"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Farbmodell?', 3, '[{"text": "Farbgenauigkeit", "correct": true, "because": "Reproduktion"}, {"text": "Schriftart", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CMYK nutzt subtraktive Mischung. b) RGB ist für Druck geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "RGB für Bildschirme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Farbmodelle werden in der Informatik genutzt?', 5, '[{"text": "RGB", "correct": true, "because": "Digitale Anzeige"}, {"text": "HSL", "correct": true, "because": "Farbauswahl"}, {"text": "TXT", "correct": false, "because": "Kein Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Farbmodell unwichtig?', 3, '[{"text": "Farbkomponenten", "correct": false, "because": "Grundlage"}, {"text": "Anwendung", "correct": false, "because": "Kontext"}, {"text": "Papiergröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das CMYK-Modell additiv?', 3, '[{"text": "Nein", "correct": true, "because": "Subtraktiv"}, {"text": "Ja", "correct": false, "because": "Farbmischung anders"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das HSL-Modell für Bildschirme genutzt wird?', 2, '[{"text": "Ja", "correct": true, "because": "Design und UI"}, {"text": "Nein", "correct": false, "because": "Anwendung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für ein Farbmodell zentral?', 4, '[{"text": "Farbkomponenten", "correct": true, "because": "Grundprinzip"}, {"text": "Papierdokumentation", "correct": false, "because": "Irrelevant"}, {"text": "Netzwerkgeschwindigkeit", "correct": false, "because": "Kein Bezug"}]');
